import {esc,money,badge,intro,empty,stat,progress,progressBar,bookingsView} from '../presentation.mjs';
export function instructorOverview({state,metrics,filter}) { return `${intro('Welcome, '+state.me.name,'Your learners, lessons and school plan collections.')}<div class="stats">${stat('Active learners',metrics.learners_count||0)}${stat("Today's lessons",metrics.today_lessons||0)}${stat('Upcoming lessons',metrics.upcoming_lessons||0)}${stat('Plan collections',money(metrics.total_earnings))}</div><section class="section-gap"><h2>Teaching schedule</h2>${bookingsView(state.bookings,'instructor',filter)}</section>`; }
export function learnersView({learners}){return `${intro('My learners','Review progress and mark practical skills after teaching them.')}<div class="cards">${learners.map(l=>{const p=progress(l.lessons);return `<section class="panel panel-pad"><h2>${esc(l.learner_name)}</h2><p>${esc(l.phone)} · ${esc(l.plan_name)}</p><p>${l.credits_remaining}/${l.credits_total} credits left</p>${progressBar('Theory',p.theory)}${progressBar('Practical',p.practical)}${l.lessons.filter(x=>x.kind==='practical').map(x=>`<div class="syllabus-item"><span>${esc(x.title)}</span>${x.completed?badge('completed'):`<button class="secondary" data-practical="${esc(x.id)}" data-learner="${esc(l.learner_id)}">Mark done</button>`}</div>`).join('')}</section>`;}).join('')||empty('No learners yet','Paid learners assigned to you will appear here.')}</div>`;}
